export class ParseError extends Error {}

const fail = (m) => { throw new ParseError(m) }
const isWs = (c) => c === ' ' || c === '\t'
const isNameChar = (c) => c !== undefined && /^[A-Za-z0-9_-]$/.test(c)
const D = '\\d+(?:_\\d+)*'
const INT = new RegExp(`^[+-]?${D}$`)
const FLOAT = new RegExp(`^[+-]?${D}(?:\\.${D})?(?:[eE][+-]?${D})?$`)

const newTable = (hdr) => ({ t: 'table', m: new Map(), hdr })

/** Parses one line's content, tracking position in `s`. */
class Line {
  constructor(s) { this.s = s; this.i = 0 }
  get c() { return this.s[this.i] }
  ws() { while (isWs(this.c)) this.i++ }
  /** True at the end of the line or at a comment start. */
  atEnd() { const c = this.c; return c === undefined || c === '#' || c === ';' }

  string() {
    const q = this.c
    this.i++
    let out = ''
    if (q === "'") {
      const j = this.s.indexOf("'", this.i)
      if (j < 0) fail('unterminated string')
      out = this.s.slice(this.i, j)
      this.i = j + 1
      return out
    }
    for (;;) {
      const c = this.c
      if (c === undefined) fail('unterminated string')
      this.i++
      if (c === '"') return out
      if (c !== '\\') { out += c; continue }
      const e = this.c
      if (e === undefined) fail('unterminated string')
      this.i++
      if (e === '"') out += '"'
      else if (e === '\\') out += '\\'
      else if (e === 'n') out += '\n'
      else if (e === 't') out += '\t'
      else if (e === 'r') out += '\r'
      else if (e === '0') out += '\0'
      else if (e === 'u') {
        const h = this.s.slice(this.i, this.i + 4)
        if (!/^[0-9A-Fa-f]{4}$/.test(h)) fail('invalid escape \\u')
        out += String.fromCharCode(parseInt(h, 16))
        this.i += 4
      } else {
        const cp = String.fromCodePoint(this.s.codePointAt(this.i - 1))
        fail('invalid escape \\' + cp)
      }
    }
  }

  name() {
    const c = this.c
    if (c === '"' || c === "'") return this.string()
    const st = this.i
    while (isNameChar(this.c)) this.i++
    if (this.i === st) fail('expected a name')
    return this.s.slice(st, this.i)
  }

  dotted() {
    const keys = [this.name()]
    for (;;) {
      const save = this.i
      this.ws()
      if (this.c !== '.') { this.i = save; return keys }
      this.i++
      this.ws()
      keys.push(this.name())
    }
  }

  value(path) {
    const c = this.c
    if (c === undefined || c === '#' || c === ';' || c === ',' || c === ']' || c === '}') fail('expected a value')
    if (c === '"' || c === "'") return { t: 'string', v: this.string() }
    if (c === '[') return this.array(path)
    if (c === '{') return this.inline(path)
    const st = this.i
    while (this.c !== undefined && !isWs(this.c) && this.c !== ',' && this.c !== ']' && this.c !== '}') this.i++
    const w = this.s.slice(st, this.i)
    if (w === 'true' || w === 'false') return { t: 'boolean', v: w === 'true' }
    if (INT.test(w)) return { t: 'integer', v: BigInt(w.replace(/_/g, '').replace(/^\+/, '')) }
    if (FLOAT.test(w)) return { t: 'float', v: Number(w.replace(/_/g, '')) }
    fail('invalid value ' + w)
  }

  array(path) {
    this.i++
    const items = []
    for (;;) {
      this.ws()
      if (this.atEnd()) fail('unterminated array')
      if (this.c === ']') { this.i++; break }
      items.push(this.value(path))
      this.ws()
      if (this.c === ',') { this.i++; continue }
      if (this.c === ']') { this.i++; break }
      if (this.atEnd()) fail('unterminated array')
      fail('trailing text after a value')
    }
    return { t: 'array', items, aot: false }
  }

  inline(path) {
    this.i++
    const tbl = newTable(true)
    this.ws()
    if (this.c === '}') { this.i++; return tbl }
    for (;;) {
      this.ws()
      if (this.atEnd()) fail('unterminated inline table')
      const keys = this.dotted()
      this.ws()
      if (this.c !== '=') fail('expected = in an inline table')
      this.i++
      this.ws()
      const full = path.concat(keys)
      const v = this.value(full)
      assign(tbl, path, keys, v)
      this.ws()
      if (this.c === ',') { this.i++; continue }
      if (this.c === '}') { this.i++; return tbl }
      if (this.atEnd()) fail('unterminated inline table')
      fail('trailing text after a value')
    }
  }
