/** Steps into `node` for walking: a table, or the last table of an array of tables. */
function step(node) {
  if (node.t === 'table') return node
  if (node.t === 'array' && node.aot) return node.items[node.items.length - 1]
  return null
}

function walk(tbl, base, keys, p) {
  let cur = tbl
  for (let k = 0; k < keys.length; k++) {
    p.push(keys[k])
    let ch = cur.m.get(keys[k])
    if (!ch) { ch = newTable(false); cur.m.set(keys[k], ch) }
    const nx = step(ch)
    if (!nx) fail(`${[...base, ...p].join('.')} is not a table`)
    cur = nx
  }
  return cur
}

function assign(tbl, base, keys, v) {
  const p = []
  const cur = walk(tbl, base, keys.slice(0, -1), p)
  const last = keys[keys.length - 1]
  if (cur.m.has(last)) fail(`key ${[...base, ...keys].join('.')} is defined twice`)
  cur.m.set(last, v)
}

