          if (ln.c === ']') ln.i++
          else if (ln.atEnd()) fail('unterminated table header')
          else fail('trailing text after a table header')
        }
        ln.ws()
        if (!ln.atEnd()) fail('trailing text after a table header')
        const p = []
        const parent = walk(root, [], keys.slice(0, -1), p)
        const last = keys[keys.length - 1]
        const full = keys.join('.')
        const ex = parent.m.get(last)
        if (!aot) {
          if (!ex) { cur = newTable(true); parent.m.set(last, cur) }
          else if (ex.t !== 'table') fail(`${full} is not a table`)
          else if (ex.hdr) fail(`table ${full} is defined twice`)
          else { ex.hdr = true; cur = ex }
        } else {
