            const a = { t: 'array', items: [], aot: true }
            parent.m.set(last, a)
            cur = newTable(true)
            a.items.push(cur)
          } else if (ex.t !== 'array' || !ex.aot) fail(`${full} is not an array of tables`)
          else { cur = newTable(true); ex.items.push(cur) }
        }
        curPath = keys
        continue
      }
      const keys = ln.dotted()
      ln.ws()
      if (ln.c !== '=') fail('expected key = value')
      ln.i++
      ln.ws()
      const v = ln.value([...curPath, ...keys])
      ln.ws()
      if (!ln.atEnd()) fail('trailing text after a value')
      assign(cur, curPath, keys, v)
    } catch (e) {
      if (e instanceof ParseError) e.message = `line ${n + 1}: ${e.message}`
      throw e
    }
  }
  return root
